INSERT INTO TRANSLATIONS VALUES ('ชื่อกิลยาว 3–20 ตัวอักษร','guild names are 3–20 characters');
INSERT INTO TRANSLATIONS VALUES ('สร้างกิล เชิญและขอเข้าร่วม แบ่ง EXP อัปเลเวลกิล และโบนัส EXP','Creating a guild, inviting or requesting to join, sharing EXP, leveling the guild up, and its EXP bonus');
INSERT INTO TRANSLATIONS VALUES (' · หัวกิลก็เชิญผู้เล่นเข้ากิลตรง ๆ ได้เช่นกัน (คำเชิญมีอายุ 60 วินาที)',' · The leader can also invite players directly (invitations stay open 60 seconds)');
