INSERT INTO TRANSLATIONS VALUES ('โอกาสตีโดน = ${HIT_CHANCE.even * 100}% + (HIT − FLEE มอน) × ${HIT_CHANCE.perPoint * 100}% ต่อแต้ม<br>','Hit chance = ${HIT_CHANCE.even * 100}% + (HIT − monster FLEE) × ${HIT_CHANCE.perPoint * 100}% per point<br>');
INSERT INTO TRANSLATIONS VALUES ('ต่ำสุด ${HIT_CHANCE.min * 100}% (ต่อให้ HIT ต่ำกว่ามากแค่ไหน) · สูงสุด ${HIT_CHANCE.max * 100}% (HIT เกิน FLEE มอน 20 ขึ้นไปคือโดนชัวร์)<br>','Floor ${HIT_CHANCE.min * 100}% (no matter how far behind your HIT is) · ceiling ${HIT_CHANCE.max * 100}% (HIT 20 or more over the monster''s FLEE always lands)<br>');
INSERT INTO TRANSLATIONS VALUES ('FLEE ของมอน = 100 + 2 × เลเวล (ปัดเศษ) — มอนเลเวลลึกยิ่งหลบเราง่ายขึ้น ต้องมี HIT ตามให้ทัน','Monster FLEE = 100 + 2 × level (rounded) — a deeper monster dodges you more easily, so you need HIT to keep up');
INSERT INTO TRANSLATIONS VALUES ('โอกาสหลบ (ก่อนหักเพดาน) = (FLEE เรา − เลเวลเรา) × 0.8% ÷ 1.3 — ตัวหาร 1.3 มาจากมอนแม่นขึ้น 30% เวลาตีผู้เล่น (ทั้งมอนทั่วไปและบอสเท่ากัน)<br>','Dodge chance (before the cap) = (your FLEE − your level) × 0.8% ÷ 1.3 — the ÷1.3 comes from monsters swinging 30% more accurately at players (the same for regular monsters and bosses)<br>');
INSERT INTO TRANSLATIONS VALUES ('FLEE จากอุปกรณ์/การ์ดนับได้ไม่เกิน ${Math.round(GEAR_FLEE_DODGE_CAP * 100)}% ของโอกาสหลบ ส่วน FLEE จาก AGI/LUK/Fleet Foot ไม่มีเพดาน<br>','FLEE from gear/cards counts for at most ${Math.round(GEAR_FLEE_DODGE_CAP * 100)}% of the dodge chance; FLEE from AGI/LUK/Fleet Foot has no cap<br>');
INSERT INTO TRANSLATIONS VALUES ('เพดานโอกาสหลบจริง: <b>95%</b> กับมอนทั่วไป, <b>87%</b> กับมอนที่เป็นบอส (Crowned) · เวทหลบไม่ได้เลย','Real dodge ceiling: <b>95%</b> against a regular monster, <b>87%</b> against a boss (Crowned) · spells can never be dodged');
