INSERT INTO TRANSLATIONS VALUES ('คริติคอลและเจาะเกราะ (Critical / Pierce)','Critical & Pierce');
INSERT INTO TRANSLATIONS VALUES ('คริติคอลตีโดนเสมอ ข้ามการเช็ค HIT/FLEE ไปเลย และดาเมจคูณ 2 บวกโบนัสคริดาเมจเพิ่มเติมจากพาสซีฟ อุปกรณ์ หรือการ์ด','A critical always lands, skipping the HIT/FLEE check entirely, and doubles the damage plus any extra crit-damage bonus from passives, gear or cards');
INSERT INTO TRANSLATIONS VALUES ('<b>คริติคอลไม่ทะลุเกราะ</b> — ต่างจากเกมแนว Ragnarok ทั่วไป ดาเมจคริติคอลยังโดนหักด้วย DEF% / MDEF% ของมอนสเตอร์เหมือนดาเมจปกติทุกประการ','<b>A critical does not ignore armor</b> — unlike most Ragnarok-style games, critical damage is still reduced by the monster''s DEF% / MDEF%, exactly like normal damage');
INSERT INTO TRANSLATIONS VALUES ('เจาะกาย (pierce) และเจาะเวท (mpierce) ลดสัดส่วน DEF%/MDEF% ที่โดนหัก ใช้ได้กับดาเมจคริติคอลด้วย เพดานสูงสุด ${SPECIAL_CAPS.pierce}%','Armor pierce (pierce) and magic pierce (mpierce) reduce the share of DEF%/MDEF% that gets deducted, including on critical hits — capped at ${SPECIAL_CAPS.pierce}%');
INSERT INTO TRANSLATIONS VALUES ('ดาเมจ = ATK × ตัวคูณคริ (×2 ถ้าคริ บวกคริดาเมจเพิ่ม) × (1 − DEF% มอน × (1 − pierce%))<br>','Damage = ATK × crit multiplier (×2 if critical, plus any extra crit damage) × (1 − monster DEF% × (1 − pierce%))<br>');
INSERT INTO TRANSLATIONS VALUES ('มอนสเตอร์ Elite','Elite Monsters');
INSERT INTO TRANSLATIONS VALUES ('มอนธรรมดาทุกตัวในทุกแมพล่ามีโอกาส ${pct(ELITE.chance)} ที่จะเกิดใหม่เป็น Elite แทน — ขึ้นชื่อ ★ Elite และตัวใหญ่กว่าเดิม โทนสีอุ่นกว่าเดิม','Any ordinary monster on any hunting map has a ${pct(ELITE.chance)} chance to respawn as an Elite instead — marked ★ Elite, bigger than normal, with a warmer color tint');
INSERT INTO TRANSLATIONS VALUES ('Elite มี HP ×${ELITE.hp}, ให้ EXP และดรอป ×${ELITE.reward}, โอกาสดรอปสูงขึ้น ×${ELITE.luck} เท่าตัวธรรมดา — แลกกับดาเมจที่ตีแรงขึ้นแค่ ×${ELITE.damage} เท่านั้น','An Elite has ×${ELITE.hp} HP, gives ×${ELITE.reward} EXP and drops, and ×${ELITE.luck} the drop luck of a normal monster — but its damage only goes up by ×${ELITE.damage}');
INSERT INTO TRANSLATIONS VALUES ('บอส (Crowned) ไม่มีวันเกิดเป็น Elite — Elite คือขั้นกลางระหว่างมอนธรรมดากับบอสประจำแมพ','A boss (Crowned) never becomes an Elite — an Elite is the middle step between an ordinary monster and the map''s boss');
