INSERT INTO TRANSLATIONS VALUES ('ยาฟื้นฟู HP/SP','HP/SP Potions');
INSERT INTO TRANSLATIONS VALUES ('โอกาสต่อการเปิด 1 หีบ','Chance per Box Opened');
INSERT INTO TRANSLATIONS VALUES ('อิง ASPD','Based on ASPD');
