INSERT INTO TRANSLATIONS VALUES ('เปิดเพื่อสุ่มยา การ์ด หรืออุปกรณ์','Opens to randomly give a potion, card, or equipment');
INSERT INTO TRANSLATIONS VALUES ('การ์ดบอส ','Boss Card ');
INSERT INTO TRANSLATIONS VALUES ('ตัวที่มอนสเตอร์ดรอปคูณสเตตัสด้วยขั้น I–V ของมอนสเตอร์ แล้วแถม FLEE/HIT และสเตตัสสุ่มเหมือนอุปกรณ์สุ่มทั่วไป ส่วนตัวที่ซื้อจากร้านค้า เควสต์ และ Mystery Relic Box ยังเป็นสเตตัสคงที่','monster-dropped copies multiply the piece''s stats by the monster''s I–V tier and add FLEE/HIT and random stats like ordinary rolled gear, while shop, quest and relic-box copies keep fixed stats');
INSERT INTO TRANSLATIONS VALUES ('โดยสุ่มเท่า ๆ กันจากทุกชิ้นที่','rolled with equal odds among every piece whose');
INSERT INTO TRANSLATIONS VALUES ('พาสซีฟที่เรียนแล้วติดตัวไปทุกอาชีพ และตัวที่มีเงื่อนไขอาวุธ','Learned passives carry over to every class, including weapon-gated ones');
INSERT INTO TRANSLATIONS VALUES ('อัตราดรอป ช่องถนัดของมอนสเตอร์ และแหล่งดรอปของอุปกรณ์ระบุชื่อทุกชิ้น','Drop rates, each monster''s favored slot, and the source of every named piece of equipment');
INSERT INTO TRANSLATIONS VALUES ('ตารางค่าประสบการณ์ที่ต้องใช้ในแต่ละเลเวล และ','Table of EXP required at each level, and ');
INSERT INTO TRANSLATIONS VALUES ('การ์ดมอนสเตอร์ ','Monster Card ');
INSERT INTO TRANSLATIONS VALUES ('สกิลอาชีพ ','Class Skill ');
INSERT INTO TRANSLATIONS VALUES ('โจมตีติดสถานะ ','Attacks inflict ');
INSERT INTO TRANSLATIONS VALUES ('เกิดใหม่ทุก ','Respawns every ');
INSERT INTO TRANSLATIONS VALUES ('ค่าประสบการณ์ ','Experience Points ');
INSERT INTO TRANSLATIONS VALUES ('ไม่มีจำหน่ายในร้าน (หาจากการดรอป)','Not sold in shops (obtained from drops)');
INSERT INTO TRANSLATIONS VALUES ('(หากมีพาสซีฟ Markup ของ Merchant จะขายได้เพิ่มขึ้น)','(With the Merchant''s Markup passive, sells for more)');
INSERT INTO TRANSLATIONS VALUES ('สามารถนำไปตีบวกที่ Blacksmith ได้สูงสุด +10 (อาวุธเพิ่ม ATK, เกราะเพิ่ม % ตัดดาเมจ)','Can be refined at the Blacksmith up to +10 (weapons gain ATK, armor gains % damage reduction)');
INSERT INTO TRANSLATIONS VALUES ('1 ช่อง สามารถนำการ์ดมอนสเตอร์มาฝังได้','1 slot, a monster card can be socketed into it');
INSERT INTO TRANSLATIONS VALUES ('(พาสซีฟ Haggler ลดได้สูงสุด 20%)','(The Haggler passive reduces it by up to 20%)');
INSERT INTO TRANSLATIONS VALUES ('ดรอปจากมอนสเตอร์เท่านั้น (ไม่มีขายในร้านค้า)','Drops from monsters only (not sold in shops)');
INSERT INTO TRANSLATIONS VALUES ('ไม่มีข้อมูลการดรอปจากมอนสเตอร์ทั่วไป (ซื้อจากร้านค้าหรือเป็นรางวัลเควสต์)','No drop data from regular monsters (buy from shop or earn as a quest reward)');
INSERT INTO TRANSLATIONS VALUES ('นักผจญภัยฝึกหัด ผู้เริ่มต้นการเดินทาง สามารถเปลี่ยนอาชีพได้เมื่อ Job Lv.10','Novice Adventurer, just starting their journey. Can change class at Job Lv.10');
INSERT INTO TRANSLATIONS VALUES ('มีด (Knife), ดาบเริ่มต้น','Knife, Starter Sword');
INSERT INTO TRANSLATIONS VALUES ('นักดาบผู้แข็งแกร่ง เก่งกาจการต่อสู้ระยะประชิด พลังป้องกันสูงและ HP มหาศาล','A powerful swordsman skilled in close combat, with high defense and massive HP');
INSERT INTO TRANSLATIONS VALUES ('ดาบ (Sword, Falchion, Blade)','Swords (Sword, Falchion, Blade)');
INSERT INTO TRANSLATIONS VALUES ('จอมเวทผู้ควบคุมธาตุ ไฟ เย็น และสายฟ้า โจมตีระยะไกลด้วยพลังเวทมนตร์ MATK','A spellcaster who commands fire, cold and lightning, attacking from range with magic power (MATK)');
INSERT INTO TRANSLATIONS VALUES ('คทา (Rod, Staff)','Rods (Rod, Staff)');
INSERT INTO TRANSLATIONS VALUES ('นักธนูผู้ปราดเปรียวและแม่นยำ โจมตีระยะไกลด้วยธนู ใช้กระสุนลูกธนูเหล็ก','A swift, precise archer who attacks from range with a bow, using iron arrows as ammo');
INSERT INTO TRANSLATIONS VALUES ('คันธนู (Bow)','Bows (Bow)');
INSERT INTO TRANSLATIONS VALUES ('นักบวชผู้ศรัทธา สามารถฟื้นฟูพลังชีวิต ฮีล และมอบบัฟสนับสนุนตนเอง','A devout cleric who can restore HP, heal, and grant self-support buffs');
INSERT INTO TRANSLATIONS VALUES ('กระบอง / คทา','Mace / Rod');
INSERT INTO TRANSLATIONS VALUES ('พ่อค้าผู้เชี่ยวชาญด้านเศรษฐกิจ สามารถซื้อของถูกลง ขายได้แพงขึ้น และใช้ค้อนทุบทำดาเมจ','A merchant skilled in economics, able to buy cheaper, sell higher, and deal damage with a hammer');
INSERT INTO TRANSLATIONS VALUES ('ค้อน (Hammer)','Hammers (Hammer)');
INSERT INTO TRANSLATIONS VALUES ('โจรผู้รวดเร็วและว่องไว ค่าหลบหลีก FLEE สูง และมีโอกาสโจมตีเบิ้ลสองครั้งติด','A swift, agile thief with high evasion (FLEE) and a chance to strike twice in a row');
INSERT INTO TRANSLATIONS VALUES ('มีดคู่ (Dagger Pair, Knife)','Dual Daggers (Dagger Pair, Knife)');
INSERT INTO TRANSLATIONS VALUES ('ค่าสถานะหลักทั้ง 6 (Primary Stats)','The 6 Core Stats (Primary Stats)');
INSERT INTO TRANSLATIONS VALUES ('ระบบสเตตัสอิงตาม MMORPG คลาสสิก ตัวละครเริ่มที่ค่าสถานะ 1 และสามารถอัปได้สูงสุด 99 โดยแต้ม Status Points จะได้รับเมื่อ Base Level เพิ่มขึ้น','The stat system follows classic MMORPG conventions. Characters start each stat at 1 and can raise it up to 99; Status Points are gained as Base Level increases');
INSERT INTO TRANSLATIONS VALUES ('คำอธิบาย & ผลลัพธ์ในเกม','Description & In-Game Effect');
INSERT INTO TRANSLATIONS VALUES ('เพิ่มพลังโจมตีทางกายภาพ (ATK) สำหรับอาวุธประชิด (ดาบ/มีด/ค้อน) และเพิ่มความจุน้ำหนักกระเป๋า (+30 ต่อแต้ม)','Increases physical attack (ATK) for melee weapons (sword/knife/hammer) and increases inventory weight capacity (+30 per point)');
INSERT INTO TRANSLATIONS VALUES ('เพิ่มความเร็วในการโจมตี (ASPD) และเพิ่มอัตราการหลบหลีกการโจมตี (Flee)','Increases attack speed (ASPD) and increases the chance to evade attacks (Flee)');
INSERT INTO TRANSLATIONS VALUES ('เพิ่มพลังชีวิตสูงสุด (MaxHP), พลังป้องกันทางกายภาพ (DEF) และอัตราการฟื้นฟู HP ธรรมชาติ','Increases maximum HP (MaxHP), physical defense (DEF), and the natural HP recovery rate');
INSERT INTO TRANSLATIONS VALUES ('เพิ่มพลังโจมตีเวทมนตร์ (MATK), พลังป้องกันเวท (MDEF), ค่า SP สูงสุด และอัตราฟื้นฟู SP','Increases magic attack (MATK), magic defense (MDEF), max SP, and SP recovery rate');
INSERT INTO TRANSLATIONS VALUES ('เพิ่มความแม่นยำในการโจมตี (Hit), เพิ่มพลังโจมตีอาวุธธนู (Bow ATK) และลดระยะเวลาการร่ายเวท (150 DEX ไร้หลอดร่าย)','Increases hit accuracy (Hit), increases bow attack (Bow ATK), and reduces cast time (150 DEX removes the cast bar)');
INSERT INTO TRANSLATIONS VALUES ('เพิ่มอัตราการติดคริติคอล (Critical Rate) และ Perfect Dodge','Increases critical chance (Critical Rate) and Perfect Dodge');
INSERT INTO TRANSLATIONS VALUES ('สูตรค่าใช้จ่ายแต้มอัปสเตตัส: แต้มที่ต้องใช้ = floor((Stat - 1) / 10) + 2','Stat point cost formula: points required = floor((Stat - 1) / 10) + 2');
INSERT INTO TRANSLATIONS VALUES ('(เช่น ค่า 1→2 ใช้ 2 แต้ม, ค่า 11→12 ใช้ 3 แต้ม ... ค่า 91→92 ใช้ 11 แต้ม)','(e.g. 1→2 costs 2 points, 11→12 costs 3 points ... 91→92 costs 11 points)');
INSERT INTO TRANSLATIONS VALUES ('ระบบการตีบวก (Refining System)','Refining System');
INSERT INTO TRANSLATIONS VALUES ('นำอุปกรณ์สวมใส่ (ดาบ, โล่, เกราะ, หมวก, ผ้าคลุม, รองเท้า) ไปตีบวกได้ที่ NPC ช่างตีเหล็ก (Blacksmith) สูงสุดระดับ +10 หากล้มเหลวไอเทมและการ์ดจะแตกสลาย','Take equipment (swords, shields, armor, hats, garments, shoes) to the Blacksmith NPC to refine it up to +10; on failure, the item and its socketed cards are destroyed');
INSERT INTO TRANSLATIONS VALUES ('ค่าใช้จ่ายตีบวก (Silver) = 100 × (ระดับปัจจุบัน + 1)²','Refine cost (Silver) = 100 × (current level + 1)²');
INSERT INTO TRANSLATIONS VALUES ('โบนัสดาบ: +2 ATK ต่อขั้น (+1 ถึง +4), +3 ATK (+5 ถึง +7), +4 ATK (+8 ถึง +9), +5 ATK (+10) รวม +30 ATK ที่ +10','Sword bonus: +2 ATK per level (+1 to +4), +3 ATK (+5 to +7), +4 ATK (+8 to +9), +5 ATK (+10), totaling +30 ATK at +10');
INSERT INTO TRANSLATIONS VALUES ('อาวุธสายเวท (Rod, Staff — อาวุธที่มี MATK แต่ไม่มี ATK): โบนัสทุกขั้นเข้า MATK แทน ATK ด้วยจำนวนเท่ากัน รวม +30 MATK ที่ +10','Magic weapons (Rod, Staff — weapons with MATK but no ATK): every level''s bonus goes to MATK instead of ATK by the same amount, totaling +30 MATK at +10');
INSERT INTO TRANSLATIONS VALUES ('โบนัสชุดเกราะ: แต่ละระดับ +1 จะลดดาเมจที่ได้รับ 1% (Refine Defense Shield ตัดดาเมจสูงสุด 50-60%)','Armor bonus: each +1 level reduces damage taken by 1% (Refine Defense Shield caps at 50-60% damage reduction)');
INSERT INTO TRANSLATIONS VALUES ('Silver ที่ใช้','Silver Used');
INSERT INTO TRANSLATIONS VALUES ('100% (ปลอดภัย)','100% (Safe)');
INSERT INTO TRANSLATIONS VALUES ('ปลอดภัย ไม่แตก','Safe, no destruction');
INSERT INTO TRANSLATIONS VALUES ('ทุกครั้งที่ล้มมอนสเตอร์ 1 ตัว เกมจะสุ่มของแต่ละหมวด','Every time you defeat a monster, the game rolls each loot category');
INSERT INTO TRANSLATIONS VALUES ('จึงอาจได้หลายอย่างพร้อมกันหรือไม่ได้อะไรเลยก็ได้ ตัวเลขทั้งหมดด้านล่างดึงจากโค้ดเกมจริง และใช้เหมือนกันทั้งโหมดออนไลน์และออฟไลน์','so you may get several things at once or nothing at all. All numbers below are pulled straight from the game code and are the same in both online and offline modes');
INSERT INTO TRANSLATIONS VALUES ('โอกาสต่อการฆ่า 1 ตัว','Chance per kill');
INSERT INTO TRANSLATIONS VALUES ('(Prism Hopper ให้ Prism Crystal แทน)','(Prism Hopper gives Prism Crystal instead)');
INSERT INTO TRANSLATIONS VALUES ('สุ่มได้ 1 อย่าง: ','Rolls 1 of: ');
INSERT INTO TRANSLATIONS VALUES ('ยาฟื้น HP ตามระดับแมพ','HP Potion matching the map''s level');
INSERT INTO TRANSLATIONS VALUES ('มอนสเตอร์ทุกสายพันธุ์ดรอปอุปกรณ์สุ่มสเตตัสได้ครบทุกช่อง โดยช่องถนัดของสายพันธุ์นั้นออกบ่อยกว่าช่องอื่น','Every monster species can drop Random-Stat equipment in every slot, with that species'' favored slot appearing more often than the rest, by');
INSERT INTO TRANSLATIONS VALUES ('% ของอุปกรณ์ที่ดรอปเป็นอุปกรณ์ระบุชื่อ (เช่น Blade, Staff, Coat, Helm, Clip) สุ่มจากชิ้นที่เลเวลสวมใส่ไม่เกินเลเวลมอนสเตอร์ +10 ทุกชิ้นจึงมีแหล่งดรอป','% of dropped equipment is Named equipment (e.g. Blade, Staff, Coat, Helm, Clip), rolled among pieces whose equip level does not exceed the monster''s level +10, so every piece has a drop source');
INSERT INTO TRANSLATIONS VALUES ('ขั้นของอาวุธและอุปกรณ์ที่ดรอป (Gear Tier I–V)','Tier of Dropped Weapons and Equipment (Gear Tier I–V)');
INSERT INTO TRANSLATIONS VALUES ('ขั้นของไอเทม = ceil(เลเวลมอนสเตอร์ / 20) จำกัดที่ 1–5','Item tier = ceil(monster level / 20), capped at 1–5');
INSERT INTO TRANSLATIONS VALUES ('ค่าสเตตัสทุกตัวถูกคูณด้วยเลขขั้น — อาวุธขั้น V จึงแรงเป็น 5 เท่าของขั้น I ที่สุ่มได้เท่ากัน','Every stat is multiplied by the tier number — a Tier V weapon is therefore 5x as strong as an identically-rolled Tier I weapon');
INSERT INTO TRANSLATIONS VALUES ('อาวุธ (sword): ATK = (2–6) × ขั้น · เกราะ/โล่/หมวก/ผ้าคลุม/รองเท้า: DEF = (1–3) × ขั้น','Weapons (sword): ATK = (2–6) × tier · Armor/Shield/Hat/Garment/Shoes: DEF = (1–3) × tier');
INSERT INTO TRANSLATIONS VALUES ('แหวนซ้าย (accessory1): CRIT = (1–3) × ขั้น · แหวนขวา (accessory2): MATK = (1–3) × ขั้น และ SP = (5–15) × ขั้น (สุ่มแยกจาก MATK)','Left Ring (accessory1): CRIT = (1–3) × tier · Right Ring (accessory2): MATK = (1–3) × tier and SP = (5–15) × tier (rolled separately from MATK)');
INSERT INTO TRANSLATIONS VALUES ('แว่นตา/ผ้าพันคอ: MDEF = (1–3) × ขั้น · ลูกธนู (ammo): ATK = (1–3) × ขั้น','Glasses/Scarf: MDEF = (1–3) × tier · Arrows (ammo): ATK = (1–3) × tier');
INSERT INTO TRANSLATIONS VALUES ('ทุกชิ้นได้ FLEE เพิ่ม (1–4) × ขั้น และชิ้นที่ไม่ใช่สายเวทได้ HIT เพิ่มเท่ากัน (ของสายเวทไม่ติด HIT เพราะเวทไม่มีพลาด)','Every piece also gains FLEE, (1–4) × tier, and every non-caster piece gains HIT by the same amount (caster gear carries no HIT, since spells never miss)');
INSERT INTO TRANSLATIONS VALUES ('สเตตัสหลัก (STR/AGI/VIT/INT/DEX/LUK): สุ่มมา 1 ตัว (มีโอกาส 25% ได้ 2 ตัว) ตัวละ (1–3) × ขั้น','Primary stats (STR/AGI/VIT/INT/DEX/LUK): 1 is rolled (25% chance of getting 2), each (1–3) × tier');
INSERT INTO TRANSLATIONS VALUES ('% ของอุปกรณ์ที่ดรอปเป็นอุปกรณ์ระบุชื่อ (เช่น Blade, Staff, Coat, Helm, Clip) สุ่มจากชิ้นที่เลเวลสวมใส่ไม่เกินเลเวลมอนสเตอร์ ทุกชิ้นจึงมีแหล่งดรอป','% of dropped equipment is Named equipment, rolled among pieces whose equip level does not exceed the monster''s level, so every piece has a drop source');
INSERT INTO TRANSLATIONS VALUES ('World Boss (Crowned Prism Hopper, Lv.100) ดรอปอุปกรณ์ขั้น V แน่นอน 100% ทุกครั้งที่ล้ม · อุปกรณ์ดรอปทุกขั้นนำไปตีบวกต่อได้ตามปกติ','The World Boss (Crowned Prism Hopper, Lv.100) drops Tier V equipment 100% of the time it''s defeated · Equipment of any tier can be refined normally afterward');
INSERT INTO TRANSLATIONS VALUES ('สกิลพาสซีฟเรียนครั้งเดียวแล้วทำงานตลอด ไม่ต้องกดใช้และไม่กินช่อง Hotbar จุดสำคัญคือ ','Passive skills are learned once and always active — no need to activate them, and they take no Hotbar slot. The key point: ');
INSERT INTO TRANSLATIONS VALUES (' — เปลี่ยนอาชีพแล้วโบนัสยังทำงานอยู่ ต่างจากสกิลกดใช้ที่ใช้ได้เฉพาะตอนเล่นอาชีพเจ้าของสกิล',' — the bonus keeps working after changing class, unlike active skills, which only work while playing the class that owns them');
INSERT INTO TRANSLATIONS VALUES ('โบนัสพาสซีฟ = ผลรวมของพาสซีฟทุกตัวที่เคยเรียน ไม่ว่าตอนนี้เล่นอาชีพอะไร','Passive bonus = the sum of every passive ever learned, regardless of the class currently played');
INSERT INTO TRANSLATIONS VALUES ('แต้มสกิลของอาชีพปัจจุบัน = Job Level ของอาชีพนั้น − ระดับสกิลที่ลงไว้ในอาชีพนั้น (แต่ละอาชีพมีแต้มของตัวเอง ไม่แย่งกัน)','Current class''s skill points = that class''s Job Level − skill levels already invested in that class (each class has its own points, they don''t compete)');
INSERT INTO TRANSLATIONS VALUES ('การเปลี่ยนอาชีพไม่ลบสกิลที่เรียนไว้ · Job Level และค่าสเตตัสของแต่ละอาชีพถูกเก็บแยกและกลับมาเหมือนเดิมเมื่อสลับกลับ','Changing class does not erase learned skills · Each class''s Job Level and stats are stored separately and return exactly as they were when you switch back');
INSERT INTO TRANSLATIONS VALUES ('อัประดับพาสซีฟได้เฉพาะตอนเล่นอาชีพเจ้าของสกิล และต้องมี Job Level ถึงเกณฑ์ · สูงสุดระดับ 10','You can only rank up a passive while playing the class that owns it, and only once Job Level meets the requirement · Maximum rank 10');
INSERT INTO TRANSLATIONS VALUES ('โจมตีสองครั้งต้องถืออาวุธประชิด (HIT ได้เสมอ)','The double-hit requires a melee weapon (the HIT bonus always applies)');
INSERT INTO TRANSLATIONS VALUES ('มีผลเฉพาะตอนถือ Bow ซึ่งมีแต่ Archer ที่ใส่ได้ · ระยะที่เพิ่มใช้ได้ทุกนัด แต่มอนที่โดนยิงจะวิ่งเข้ามาหา','Only works while holding a Bow, which only the Archer can equip · the extra range applies to every shot, but a monster you shoot runs up to you');
INSERT INTO TRANSLATIONS VALUES ('✔ ได้ผลเต็มทุกอาชีพ','✔ Full effect on every class');
INSERT INTO TRANSLATIONS VALUES ('ระบบฟื้นฟู HP และ SP ตามธรรมชาติ (Natural Regen)','Natural HP and SP Recovery (Natural Regen)');
INSERT INTO TRANSLATIONS VALUES ('ตัวละครจะฟื้นฟู HP ทุกๆ 6 วินาที และฟื้นฟู SP ทุกๆ 2 วินาที หากถูกโจมตี การฟื้นฟู HP จะหยุดชั่วคราวเป็นเวลา 8 วินาที','Characters recover HP every 6 seconds and SP every 2 seconds. Taking damage pauses HP recovery for 8 seconds');
INSERT INTO TRANSLATIONS VALUES ('ฟื้นฟู HP ต่อรอบ = floor(MaxHP / 200) + floor(VIT / 5) (ขั้นต่ำ 1 HP)','HP recovered per tick = floor(MaxHP / 200) + floor(VIT / 5) (minimum 1 HP)');
INSERT INTO TRANSLATIONS VALUES ('การนั่งพัก (Sit Down): ช่วยให้ฟื้นฟู HP และ SP เร็วขึ้นเป็น 2 เท่าตัว!','Sitting Down: makes HP and SP recovery 2x faster!');
